import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Search for solutions (p, q) for k^2 = 4p^3 - 3
# We search up to a reasonable prime p limit to check if the solutions are bounded.
# Previous check showed p=7 gives q=19.
P_LIMIT = 50 
solutions = []

print(f"Searching for solutions up to prime p = {P_LIMIT}...")

primes = []
i = 2
while i <= P_LIMIT:
    if is_prime(i):
        primes.append(i)
    i += 1

for p in primes:
    N = 4 * (p**3) - 3
    if is_square(N):
        k = math.isqrt(N)

        # q = (1 + k) / 2. Since k^2 = 4p^3 - 3, k must be odd (k^2 = 1 mod 4), so 1+k is even.
        q = (1 + k) // 2

        # Check constraints: q must be prime and q != p
        if is_prime(q) and q != p:
            solutions.append((q, p))

print("--- Found Solutions (q, p) ---")
if solutions:
    for q, p in solutions:
        print(f"q={q}, p={p}. Check: {q}^2 - {q} + 1 = {p}^3 ({p**3})")
else:
    print("No solutions found in the search range.")

print("\nSearch complete.")

